// Lit la réponse de Gemini (candidates[0].content.parts) ou de Groq Fallback (choices[0].message.content),
// au format texte à balises : ===KEYWORDS=== ... ===CV_LATEX=== ... ===COVER_LETTER=== ... ===END===
// puis contrôle déterministe : référentiel réel (cv_source.tex + projects_catalog.json), ATS Keyword Match Score,
// skill gaps, surestimations (overclaim), formules interdites et structure de la lettre. Rien n'est corrigé en
// silence : les écarts sont signalés dans le message Telegram.
function normalizeLatex(latex) {
  // Espaces et tirets typographiques invisibles que pdflatex ne sait pas composer -> équivalents LaTeX/ASCII.
  latex = latex
    .replace(/[\u00A0\u202F]/g, '~')
    .replace(/[\u2002-\u200A\u205F]/g, ' ')
    .replace(/[\u200B-\u200D\u2060\uFEFF]/g, '')
    .replace(/[\u2010\u2011\u2212]/g, '-');
  // '&' non échappé ("DevOps & Architecture") : erreur "Misplaced alignment tab". On l'échappe, sauf si le
  // document contient un environnement où '&' sépare légitimement des colonnes.
  if (!/\\begin\{(tabular\*?|tabularx|longtable|array|align\*?|alignat\*?|eqnarray\*?|[pbvBV]?matrix|cases|split)\}/.test(latex)) {
    latex = latex.replace(/(?<!\\)&/g, '\\&');
  }
  // Filet de sécurité : sur une seule ligne, un '%' non échappé commenterait tout le reste du document.
  if (latex.includes('\n')) return latex;
  return latex
    .replace(/(?<!\\)%/g, '%\n')
    .replace(/\\(documentclass|usepackage|geometry|renewcommand|pagestyle|setlength|definecolor|hypersetup|setcounter|titleformat|titlespacing|setlist|newcommand|begin|end|section|item|entryheader|vspace)(?![A-Za-z])/g, '\n\\$1')
    .replace(/^\n+/, '');
}

// Nom du PDF envoyé sur Telegram : Nouaman_Haimoudi_<titre du poste>_offre.pdf
// (accents translittérés, tout sauf lettres/chiffres -> "_", 60 caractères max pour Windows).
function slugify(text) {
  const slug = String(text || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 60)
    .replace(/_+$/g, '');
  return slug || 'poste';
}
const offer = $('Extraire offre').first().json;
const pdfFilename = 'Nouaman_Haimoudi_' + slugify(offer.job_title) + '_offre.pdf';

// ---------- Normalisation de texte et recherche de termes ----------
const fold = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[\u2019`]/g, "'");
const stem = (t) => (t.length > 4 && t.endsWith('s') && !t.endsWith('ss') ? t.slice(0, -1) : t);
const STOP = new Set(['and', 'or', 'of', 'the', 'with', 'for', 'to', 'in', 'on', 'a', 'an', 'et', 'ou', 'de', 'des',
  'du', 'la', 'le', 'les', 'en', 'avec', 'pour', 'sur', 'using', 'based', 'skill', 'experience', 'knowledge',
  'connaissance', 'maitrise', 'solide', 'bonne']);
const tokens = (s) => fold(s).replace(/[^a-z0-9+#.]+/g, ' ').replace(/\.(?=\s|$)/g, ' ').split(/\s+/).filter(Boolean).map(stem);
function corpus(text) {
  const t = tokens(text);
  return { text: ' ' + t.join(' ') + ' ', set: new Set(t) };
}
function latexToText(tex) {
  const body = String(tex || '').split('\\begin{document}').pop();
  return body
    .replace(/(?<!\\)%.*$/gm, '')
    .replace(/\\href\{[^}]*\}\{([^}]*)\}/g, '$1')
    .replace(/\\([&%#_$])/g, '$1')
    .replace(/\\[a-zA-Z]+\*?(\[[^\]]*\])?/g, ' ')
    .replace(/[{}~]/g, ' ')
    .replace(/--+/g, '-');
}
const SECTION = (name) => new RegExp('\\\\section\\{' + name + '\\}([\\s\\S]*?)(?=\\\\section\\{|\\\\end\\{document\\})');
const sectionOf = (tex, name) => ((String(tex).match(SECTION(name)) || [])[1] || '');
const withoutSection = (tex, name) => String(tex).replace(SECTION(name), '');
// Synonymes : un mot-clé est reconnu si l'une de ses variantes est présente.
const ALIASES = [
  ['ci/cd', 'ci cd', 'cicd', 'continuous integration', 'continuous delivery', 'continuous deployment', 'integration continue', 'deploiement continu'],
  ['kubernetes', 'k8s'], ['javascript', 'js'], ['typescript', 'ts'], ['postgresql', 'postgres'],
  ['machine learning', 'ml', 'apprentissage automatique'], ['llm', 'llms', 'large language model', 'large language models'],
  ['rag', 'retrieval augmented generation', 'retrieval-augmented generation'], ['genai', 'generative ai', 'ia generative', 'gen ai'],
  ['ai', 'artificial intelligence', 'ia', 'intelligence artificielle'], ['nlp', 'natural language processing'],
  ['rest api', 'api rest', 'rest apis', 'restful', 'api restful'], ['conteneurisation', 'containerization', 'docker'],
  ['power bi', 'powerbi'], ['node.js', 'nodejs', 'node'], ['c#', 'csharp'], ['spring boot', 'spring'],
  ['agile', 'scrum'], ['gitlab ci', 'gitlab ci/cd', 'gitlab'], ['github actions', 'github action'],
];
function variants(term) {
  const f = fold(term).trim();
  const group = ALIASES.find((grp) => grp.includes(f));
  return group ? group : [f];
}
function hasTerm(c, term) {
  const t = tokens(term).filter((x) => !STOP.has(x));
  if (!t.length) return false;
  if (c.text.includes(' ' + t.join(' ') + ' ')) return true;
  return t.length > 1 && t.length <= 3 && t.every((x) => c.set.has(x));
}
const matches = (c, term) => variants(term).some((v) => hasTerm(c, v));

// ---------- Référentiel réel : cv_source.tex + projects_catalog.json ----------
const source = $('Mode de travail').first().json;
const sourceCv = String(source.cv_latex || '');
const projects = Array.isArray(source.projects) ? source.projects : [];
const catalogText = projects.map((p) => [p.name, p.description, ...(p.technologies || [])].join(' ')).join('\n');
// Les certifications ne prouvent pas une compétence (ex. « AWS Certified AI Practitioner » ≠ EC2/VPC/IAM).
const real_skills_repository = corpus(latexToText(withoutSection(sourceCv, 'Certifications')) + '\n' + catalogText);
const certificationsOnly = corpus(latexToText(sectionOf(sourceCv, 'Certifications')));
const CERT_NAMES = /AWS Certified AI Practitioner/gi;

// Technologies courantes cherchées dans le CV généré et la lettre, pour repérer une compétence ajoutée sans source.
const TECH = ['AWS', 'EC2', 'S3', 'RDS', 'Lambda', 'VPC', 'IAM', 'ECS', 'EKS', 'CloudWatch', 'CloudTrail', 'Auto Scaling',
  'Elastic Load Balancer', 'Azure', 'GCP', 'Google Cloud', 'Terraform', 'Ansible', 'Jenkins', 'Prometheus', 'Grafana',
  'Datadog', 'ELK', 'Elasticsearch', 'Kibana', 'Kafka', 'RabbitMQ', 'Redis', 'Helm', 'ArgoCD', 'OpenStack', 'VMware',
  'Nginx', 'Linux', 'Bash', 'PowerShell', 'VPN', 'Golang', 'Rust', 'Scala', 'Spark', 'Hadoop', 'Airflow', 'dbt',
  'Snowflake', 'Databricks', 'Tableau', 'Laravel', 'Symfony', 'Django', 'Flask', 'Node.js', 'Express', 'Next.js',
  'Angular', 'Vue.js', 'TypeScript', 'GraphQL', 'Oracle', 'SQL Server', 'Cassandra', 'Pandas', 'Scikit-learn',
  'PyTorch', 'TensorFlow', 'Keras', 'Hugging Face', 'LangChain', 'LlamaIndex', 'OpenAI', 'MLflow', 'Kubeflow',
  'SageMaker', 'Selenium', 'Jira', 'SAP', 'Salesforce', 'ETL', 'Data Warehouse'];

return $input.all().map((item, index) => {
  const j = item.json;
  let text;
  let generatedBy;
  let webQueries = [];
  if (typeof j.candidates?.[0]?.content?.parts?.[0]?.text === 'string') {
    text = j.candidates[0].content.parts.map((p) => p.text || '').join('');
    generatedBy = 'gemini';
    webQueries = j.candidates[0].groundingMetadata?.webSearchQueries || [];
  } else if (typeof j.choices?.[0]?.message?.content === 'string') {
    text = j.choices[0].message.content;
    generatedBy = 'groq';
    webQueries = (j.choices[0].message.executed_tools || []).map((t) => t.arguments || t.type).filter(Boolean);
  } else {
    throw new Error('Format de réponse inconnu (ni Gemini ni Groq) : ' + JSON.stringify(j).slice(0, 500));
  }
  const m = text.match(/===KEYWORDS===\s*([\s\S]*?)\s*===CV_LATEX===\s*([\s\S]*?)\s*===COVER_LETTER===\s*([\s\S]*?)\s*(?:===END===[\s\S]*)?$/);
  if (!m) {
    throw new Error('Balises ===KEYWORDS=== / ===CV_LATEX=== / ===COVER_LETTER=== absentes de la réponse '
      + generatedBy + ' — début : ' + text.slice(0, 300));
  }
  const cvLatex = normalizeLatex(m[2].trim().replace(/^```(?:latex|tex)?\s*/i, '').replace(/\s*```$/, ''));
  const coverLetter = m[3].trim();
  if (!cvLatex.startsWith('\\documentclass') || !cvLatex.includes('\\end{document}')) {
    throw new Error('cv_latex incomplet dans la réponse ' + generatedBy + ' (début : ' + cvLatex.slice(0, 80) + ')');
  }
  if (!coverLetter) {
    throw new Error('cover_letter vide dans la réponse ' + generatedBy);
  }

  // ---------- Mots-clés de l'offre ----------
  const keywordList = (label) => {
    const block = (m[1].match(new RegExp(label + '\\s*:\\s*([\\s\\S]*?)(?=\\n\\s*(?:MUST_HAVE|IMPORTANT|NICE_TO_HAVE|DOMAIN_KEYWORDS)\\s*:|$)')) || [])[1] || '';
    const seen = new Set();
    return block.split(/[,;\n]/).map((k) => k.replace(/^[\s\-*•]+|[\s.]+$/g, '').trim())
      .filter((k) => k && k.length <= 60 && !seen.has(fold(k)) && seen.add(fold(k)));
  };
  const keywords = {
    must_have: keywordList('MUST_HAVE'), important: keywordList('IMPORTANT'),
    nice_to_have: keywordList('NICE_TO_HAVE'), domain: keywordList('DOMAIN_KEYWORDS'),
  };

  // ---------- CV généré : couverture, skill gaps, surestimations ----------
  const generatedSkills = corpus(latexToText(withoutSection(cvLatex, 'Certifications')).replace(CERT_NAMES, ' '));
  const letterCorpus = corpus(coverLetter.replace(CERT_NAMES, ' '));
  const skill_gaps = [];
  const overclaim_warnings = [];
  const addOverclaim = (msg) => { if (!overclaim_warnings.includes(msg)) overclaim_warnings.push(msg); };
  const coverage = {};
  for (const [level, list] of [['must_have', keywords.must_have], ['important', keywords.important], ['nice_to_have', keywords.nice_to_have]]) {
    const covered = [];
    for (const kw of list) {
      const supported = matches(real_skills_repository, kw);
      const inCv = matches(generatedSkills, kw);
      if (supported && inCv) covered.push(kw);
      if (!supported) {
        const gap = matches(certificationsOnly, kw) ? kw + ' (certification uniquement)' : kw;
        if (!skill_gaps.includes(gap)) skill_gaps.push(gap);
        if (inCv) addOverclaim(kw + ' : présent dans le CV généré mais absent du référentiel réel');
      }
    }
    coverage[level] = { total: list.length, covered };
  }
  for (const kw of keywords.domain) {
    if (!matches(real_skills_repository, kw) && matches(generatedSkills, kw)) {
      addOverclaim(kw + ' : domaine revendiqué dans le CV généré mais absent du référentiel réel');
    }
  }
  for (const tech of TECH) {
    if (matches(real_skills_repository, tech)) continue;
    if (matches(generatedSkills, tech)) addOverclaim(tech + ' : présent dans le CV généré mais absent du référentiel réel');
    if (matches(letterCorpus, tech)) addOverclaim(tech + ' : cité dans la lettre (absent du référentiel réel, ne pas le présenter comme une compétence)');
  }
  // Chiffres/pourcentages : « 30 % », « reduced by 40 », « amélioré de 2x »... absents du référentiel -> suspects.
  const PERCENT = /(\d+(?:[.,]\d+)?)\s?%/g;
  const CHANGE_BY = /\b(?:increas\w*|reduc\w*|improv\w*|boost\w*|decreas\w*|cut|augment\w*|r[ée]dui\w*|r[ée]duction|am[ée]lior\w*|diminu\w*|acc[ée]l[ée]r\w*)\b[^.\n]{0,40}?\b(?:by|de|of|par)\s+(\d+(?:[.,]\d+)?)(\s?(?:%|x|fois|times))?/gi;
  const numberInRepository = (n) => new RegExp('(?<![\\d.,])' + n.replace('.', '[.,]').replace(',', '[.,]') + '(?![\\d])')
    .test(sourceCv + '\n' + JSON.stringify(projects));
  for (const text of [latexToText(cvLatex), coverLetter]) {
    for (const re of [PERCENT, CHANGE_BY]) {
      for (const hit of text.matchAll(re)) {
        const value = hit[1] + (re === PERCENT ? ' %' : (hit[2] || '').replace(/^\s*/, ' ').trimEnd());
        if (!numberInRepository(hit[1])) addOverclaim('chiffre suspect : ' + value.trim());
      }
    }
  }

  // ---------- ATS Keyword Match Score ----------
  const pct = (level) => (coverage[level].total ? Math.round((100 * coverage[level].covered.length) / coverage[level].total) : null);
  const scores = { must_have_score: pct('must_have'), important_score: pct('important'), nice_to_have_score: pct('nice_to_have') };
  const weighted = [[scores.must_have_score, 0.6], [scores.important_score, 0.3], [scores.nice_to_have_score, 0.1]]
    .filter(([s]) => s !== null);
  const weightSum = weighted.reduce((a, [, w]) => a + w, 0);
  scores.overall_keyword_match_score = weightSum ? Math.round(weighted.reduce((a, [s, w]) => a + s * w, 0) / weightSum) : null;

  // ---------- Positionnement (CV) ----------
  const header = cvLatex.split('\\begin{document}').pop().split('\\section{')[0];
  const profile = sectionOf(cvLatex, 'Profile');
  const cvTitle = latexToText((header.match(/\\color\{lightgray\}\s*([^}]*)\}/) || [])[1] || '').replace(/\s+/g, ' ').trim();
  const banned_phrase_warnings = [];
  const STUDENT = /\b(students?|etudiante?s?|undergraduate|currently studying|final[- ]year|fin d'etudes|en cours de formation|junior)\b/;
  const studentCv = fold(latexToText(withoutSection(cvLatex, 'Education'))).match(STUDENT);
  if (studentCv) banned_phrase_warnings.push('CV : « ' + studentCv[0] + ' »');
  const seniority = fold(latexToText(header + profile)).match(/\b(senior|lead|manager|principal|architect|intern|stagiaire)\b/);
  if (seniority) addOverclaim('Titre/Profile : « ' + seniority[0] + ' » non justifié');
  if (/\\includegraphics|tikzpicture|linkedin|github|portfolio|vercel/i.test(header)) {
    addOverclaim('Header : photo ou lien (LinkedIn/GitHub/Portfolio) réapparu');
  }

  // ---------- Lettre ----------
  const letterFold = fold(coverLetter);
  const BANNED = [
    [/je vous ecris/, 'Je vous écris…'], [/vif interet/, 'vif intérêt'], [/je suis actuellement/, 'Je suis actuellement…'],
    [/je souhaite (vous )?exprimer/, 'Je souhaite vous exprimer…'], [/fort(e)? de mon experience|fort(e)? de mes/, 'Fort de mon expérience'],
    [/je (reste|me tiens) a votre (entiere |totale )?disposition/, 'Je reste à votre disposition'],
    [/je serai(s)? ravi(e)?/, 'Je serais ravi de'], [/n'hesitez pas/, "N'hésitez pas…"],
    [/passionne(e)? par l'innovation|passionate about innovation/, "Passionné par l'innovation"],
    [/je vous prie d'agreer|veuillez agreer/, "Je vous prie d'agréer…"], [/i am writing|i'm writing/, 'I am writing…'],
    [/express my (strong |keen |sincere )?interest/, 'express my interest'], [/currently a student/, 'Currently a student'],
    [/currently studying/, 'I am currently studying'], [/final[- ]year student/, 'As a final-year student'],
    [/i would be delighted|i'd be delighted/, 'I would be delighted'], [/do not hesitate|don't hesitate/, 'Please do not hesitate…'],
  ];
  for (const [re, label] of BANNED) if (re.test(letterFold)) banned_phrase_warnings.push('Lettre : « ' + label + ' »');
  const studentLetter = letterFold.match(STUDENT);
  if (studentLetter) banned_phrase_warnings.push('Lettre : « ' + studentLetter[0] + ' »');

  const words = coverLetter.split(/\s+/).filter(Boolean).length;
  const paragraphs = coverLetter.split(/\n\s*\n/).map((b) => b.trim()).filter((b) => b.split(/\s+/).length >= 12).length;
  const offerCity = String(offer.location || '').split(',')[0].trim();
  const CITIES = ['casablanca', 'rabat', 'marrakech', 'tanger', 'agadir', 'fes', 'meknes', 'oujda', 'kenitra', 'tetouan', 'el jadida', 'mohammedia', 'sale'];
  const otherCity = CITIES.find((c) => c !== fold(offerCity) && c !== 'casablanca' && new RegExp('\\b' + c + '\\b').test(letterFold));
  const falseHome = letterFold.match(/(je vis a|j'habite a|je reside a|residant a|i live in|living in|i reside in)\s+(?!casablanca)[a-z-]+/);
  const titleWords = tokens(offer.job_title).filter((t) => t.length >= 4 && !['h/f', 'f/h'].includes(t));
  const letter_warnings = [];
  if (words < 180 || words > 220) letter_warnings.push(words + ' mots (attendu : 180–220)');
  if (paragraphs !== 4) letter_warnings.push(paragraphs + ' paragraphes (attendu : 4)');
  if (offer.company && !letterFold.includes(fold(offer.company))) letter_warnings.push('entreprise « ' + offer.company + ' » absente');
  if (titleWords.length && !titleWords.some((t) => letterCorpus.set.has(t))) letter_warnings.push('intitulé du poste absent');
  if (otherCity) letter_warnings.push('ville inattendue : ' + otherCity);
  if (falseHome) letter_warnings.push('fausse résidence : « ' + falseHome[0] + ' »');
  if (![...keywords.must_have, ...keywords.important].some((k) => matches(letterCorpus, k))) {
    letter_warnings.push("aucune exigence de l'offre (MUST_HAVE/IMPORTANT) citée");
  }

  // ---------- Bloc Telegram (Markdown échappé) ----------
  const esc = (s) => String(s).replace(/([_*`\[])/g, '\\$1');
  const show = (s) => (s === null ? '—' : s + '%');
  const lines = ['📊 *ATS Keyword Match*',
    'MUST-HAVE : ' + show(scores.must_have_score), 'IMPORTANT : ' + show(scores.important_score),
    'NICE-TO-HAVE : ' + show(scores.nice_to_have_score), 'GLOBAL : ' + show(scores.overall_keyword_match_score)];
  if (overclaim_warnings.length) lines.push('', '⚠️ *À vérifier avant envoi :*', ...overclaim_warnings.map((w) => '• ' + esc(w)));
  if (skill_gaps.length) lines.push('', '🔎 *Compétences demandées mais non démontrées :*', esc(skill_gaps.join(', ')));
  if (banned_phrase_warnings.length) lines.push('', '⚠️ *Formules à corriger :*', ...banned_phrase_warnings.map((w) => '• ' + esc(w)));
  if (letter_warnings.length) lines.push('', '📝 *Lettre à revoir :*', ...letter_warnings.map((w) => '• ' + esc(w)));

  return {
    json: {
      cv_latex: cvLatex, cover_letter: coverLetter, generated_by: generatedBy, pdf_filename: pdfFilename,
      cv_title: cvTitle, keywords, keyword_scores: scores, skill_gaps, overclaim_warnings, banned_phrase_warnings,
      letter_checks: { words, paragraphs, warnings: letter_warnings }, web_search_queries: webQueries,
      telegram_report: lines.join('\n'),
    },
    pairedItem: { item: index },
  };
});

