// Détection déterministe du mode de travail (par le code, pas par le modèle) dans la description de l'offre.
// Les mots-clés trouvés (français ou anglais) sont traduits en anglais avant d'être transmis au prompt :
// work_mode = "hybrid", "remote", "on-site" (plusieurs séparés par ", "), ou exactement "none".
const KEYWORDS = [
  ['remote', /t[ée]l[ée][- ]?travail/i],
  ['hybrid', /\bhybride\b/i],
  ['hybrid', /\bhybrid\b/i],
  ['remote', /\bremote\b/i],
  ['on-site', /\bon[- ]?site\b/i],
  ['on-site', /pr[ée]sentiel/i],
  ['remote', /\bhome[- ]office\b/i],
  ['on-site', /\bin[- ]person\b/i],
  ['on-site', /\bsur[- ]site\b/i],
];

return $input.all().map((item, index) => {
  const description = String(item.json.description || '');
  const found = [...new Set(KEYWORDS.filter(([, re]) => re.test(description)).map(([mode]) => mode))];
  return {
    json: { ...item.json, work_mode: found.length ? found.join(', ') : 'none' },
    pairedItem: { item: index },
  };
});
